#!/bin/sh
# Builds kaggle/finetune_g/kernel.py: carries src/finetune.py and the fold ids (filename + fold number only),
# runs the 5 folds as a queue per GPU (T4 x2), in parallel across GPUs.
cd "$(dirname "$0")/.."
B64=$(base64 < src/finetune.py | tr -d '\n')
FOLDS=$(cat cache/folds_grouped_r0.csv | base64 | tr -d '\n')
EPOCHS=${EPOCHS:-8}
cat > kaggle/finetune_g/kernel.py <<PY
# Kaggle kernel for Stage G on speaker-grouped folds. Generated by kaggle/build_finetune_g.sh from src/finetune.py.
import base64, glob, os, subprocess, sys, threading, time
import torch
from huggingface_hub import snapshot_download

OUT = "/kaggle/working"
open("/tmp/finetune.py", "w").write(base64.b64decode("$B64").decode())
open("/tmp/folds.csv", "w").write(base64.b64decode("$FOLDS").decode())
DATA = os.path.dirname(glob.glob("/kaggle/input/**/train.csv", recursive=True)[0])
snapshot_download("microsoft/wavlm-large", allow_patterns=["*.json", "*.bin", "*.safetensors"])
n = max(1, torch.cuda.device_count())
print("GPUs:", n, [torch.cuda.get_device_name(i) for i in range(n)], flush=True)
queues = [[k for k in range(5) if k % n == g] for g in range(n)]
codes = {}

def run_queue(g):
    for k in queues[g]:
        r = subprocess.run([sys.executable, "/tmp/finetune.py", "--data", DATA, "--folds", "/tmp/folds.csv",
                            "--out", OUT, "--fold", str(k), "--epochs", "$EPOCHS", "--nz"],
                           env={**os.environ, "CUDA_VISIBLE_DEVICES": str(g)})
        codes[k] = r.returncode

t0 = time.time()
th = [threading.Thread(target=run_queue, args=(g,)) for g in range(n)]
[t.start() for t in th]; [t.join() for t in th]
print("fold exit codes:", codes, "| wall time %.0f min" % ((time.time() - t0) / 60), flush=True)
print(sorted(os.listdir(OUT)), flush=True)
PY
echo "built kaggle/finetune_g/kernel.py (epochs=$EPOCHS)"
